// ticketId se extrae una sola vez, fuera del try: si el payload no trae
// ticketId no hay nada que reportar de vuelta, y así el catch nunca depende
// de volver a tocar $input (que ya funcionó una vez arriba).
const rawBody = ($input.first().json && $input.first().json.body) || $input.first().json || {};
const ticketId = rawBody.ticketId;

try {
  const title = String(rawBody.title || '').toLowerCase();
  const description = String(rawBody.description || '').toLowerCase();
  const text = `${title} ${description}`;

  // Reglas de clasificación por keywords, en orden de prioridad de match.
  const categoryRules = [
    { category: 'billing', keywords: ['factura', 'cobro', 'pago', 'suscripción', 'cancelación', 'reembolso'] },
    { category: 'technical', keywords: ['error', 'bug', 'no funciona', 'se cierra', 'crash', 'no carga', '500'] },
    { category: 'account', keywords: ['contraseña', 'email', 'cuenta', 'acceso', 'sesión', 'login'] },
  ];

  const priorityRules = [
    { priority: 'urgent', keywords: ['urgente', 'no puedo trabajar', 'crítico'] },
    { priority: 'high', keywords: ['error 500', 'cobro duplicado', 'no funciona', 'no puedo iniciar sesión'] },
    { priority: 'low', keywords: ['sugerencia', 'consulta', 'pregunta'] },
  ];

  const tags = [];

  let category = 'other';
  for (const rule of categoryRules) {
    const hit = rule.keywords.find((kw) => text.includes(kw));
    if (hit) {
      category = rule.category;
      tags.push(hit);
      break;
    }
  }

  let priority = 'medium';
  for (const rule of priorityRules) {
    const hit = rule.keywords.find((kw) => text.includes(kw));
    if (hit) {
      priority = rule.priority;
      tags.push(hit);
      break;
    }
  }

  return [{ json: { ticketId, status: 'done', priority, category, tags } }];
} catch (error) {
  return [{ json: { ticketId, status: 'failed' } }];
}

// Nodo Code "Build AI Reply" — corre después del nodo de Gemini.
const VALID_PRIORITIES = ['low', 'medium', 'high', 'urgent'];
const VALID_CATEGORIES = ['billing', 'technical', 'account', 'other'];

const webhookBody = $('Webhook').item.json.body || {};
const ticketId = webhookBody.ticketId;

const classified = $('Classify Ticket').item.json;
const fallbackPriority = classified.priority;
const fallbackCategory = classified.category;
const tags = classified.tags || [];

// AJUSTADO: la forma real que devuelve este nodo de Gemini.
const rawText =
  $json.content?.parts?.[0]?.text ??
  $json.candidates?.[0]?.content?.parts?.[0]?.text ??
  $json.text ??
  '';

function extractJson(text) {
  const withoutFences = text.replace(/```json\s*|```/g, '').trim();
  try {
    return JSON.parse(withoutFences);
  } catch {
    const match = withoutFences.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

const parsed = extractJson(rawText);

const priority =
  parsed && VALID_PRIORITIES.includes(parsed.priority) ? parsed.priority : fallbackPriority;

const category =
  parsed && VALID_CATEGORIES.includes(parsed.category) ? parsed.category : fallbackCategory;

const suggestedReply =
  parsed && typeof parsed.suggestedReply === 'string' && parsed.suggestedReply.trim().length > 0
    ? parsed.suggestedReply.trim()
    : undefined;

const result = { ticketId, status: 'done', priority, category, tags };
if (suggestedReply) {
  result.suggestedReply = suggestedReply;
}

return [{ json: result }];
